<?php
require_once '../config/database.php'; require_once '../includes/auth.php'; require_role('admin');$page_title='Панель управления';
$students=(int)$pdo->query("SELECT COUNT(*) FROM students WHERE status='active'")->fetchColumn();$groups=(int)$pdo->query('SELECT COUNT(*) FROM groups')->fetchColumn();$teachers=(int)$pdo->query('SELECT COUNT(*) FROM teachers')->fetchColumn();$todayLessons=(int)$pdo->query('SELECT COUNT(*) FROM lessons WHERE lesson_date=CURDATE()')->fetchColumn();
$attendance=(float)$pdo->query("SELECT COALESCE(ROUND(100*SUM(status IN ('PRESENT','LATE'))/NULLIF(COUNT(*),0),1),0) FROM attendance")->fetchColumn();$avgGrade=$pdo->query('SELECT ROUND(AVG(grade),2) FROM grades')->fetchColumn();
$statusCounts=['PRESENT'=>0,'ABSENT'=>0,'LATE'=>0,'EXCUSED'=>0];foreach($pdo->query('SELECT status,COUNT(*) c FROM attendance GROUP BY status')->fetchAll() as $r)$statusCounts[$r['status']]=$r['c'];$max=max(1,...array_values($statusCounts));
$recent=$pdo->query("SELECT l.lesson_date,l.start_time,l.classroom,s.name subject_name,g.name group_name FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN groups g ON g.id=l.group_id ORDER BY l.lesson_date DESC,l.start_time DESC LIMIT 7")->fetchAll();include '../includes/header.php';?>
<div class="cards"><div class="card"><div class="kpi-icon">👨‍🎓</div><div class="label">Студентов</div><div class="value"><?=$students?></div><div class="subvalue">активных</div></div><div class="card"><div class="kpi-icon">👨‍🏫</div><div class="label">Преподавателей</div><div class="value"><?=$teachers?></div></div><div class="card"><div class="kpi-icon">📅</div><div class="label">Занятий сегодня</div><div class="value"><?=$todayLessons?></div></div><div class="card"><div class="kpi-icon">✅</div><div class="label">Посещаемость</div><div class="value"><?=$attendance?>%</div></div><div class="card"><div class="kpi-icon">⭐</div><div class="label">Средний балл</div><div class="value"><?=$avgGrade?:'—'?></div></div><div class="card"><div class="kpi-icon">👥</div><div class="label">Групп</div><div class="value"><?=$groups?></div></div></div>
<div class="dashboard-grid"><div class="panel"><div class="section-head"><h2>Последние занятия</h2><a class="btn secondary" href="lessons.php">Все занятия</a></div><div class="table-wrap"><table><tr><th>Дата</th><th>Предмет</th><th>Группа</th><th>Время</th><th>Ауд.</th></tr><?php foreach($recent as $r):?><tr><td><?=date('d.m.Y',strtotime($r['lesson_date']))?></td><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=htmlspecialchars($r['group_name'])?></td><td><?=substr($r['start_time'],0,5)?></td><td><?=htmlspecialchars($r['classroom'])?></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Посещаемость</h2><div class="mini-chart"><?php foreach(['PRESENT'=>'Был','ABSENT'=>'Нет','LATE'=>'Опозд.','EXCUSED'=>'Уваж.'] as $k=>$label):$h=round($statusCounts[$k]/$max*120);?><div class="bar"><i style="height:<?=$h?>px"></i><b><?=$statusCounts[$k]?></b><span><?=$label?></span></div><?php endforeach;?></div></div></div>
<div class="panel" style="margin-top:20px"><h2>Быстрые действия</h2><div class="quick-links"><a class="quick-link" href="students.php?action=add"><b>➕ Добавить студента</b><span>Создать аккаунт и карточку студента</span></a><a class="quick-link" href="lessons.php?action=add"><b>📅 Добавить занятие</b><span>Запланировать новую пару</span></a><a class="quick-link" href="attendance.php"><b>✅ Посещаемость</b><span>Отметить присутствующих</span></a><a class="quick-link" href="grades.php"><b>⭐ Оценки</b><span>Посмотреть журнал оценок</span></a></div></div>
